// ---- phân loại lỗi + format (thay cho 6 node IF) ----
const t0 = $input.first().json;
const ex = t0.execution || {};
const wf = t0.workflow || {};
const err = ex.error || {};

const msg = String(err.message || "(khong co message)");
const stack = String(err.stack || "");
const desc = String(err.description || "");

function classify(text) {
  const s = (msg + " " + desc + " " + stack).toLowerCase();
  // 1) hạ tầng / cấu hình → cần IT, mức nghiêm trọng
  if (/insufficient|missing required credential|private key|unauthori[sz]ed|forbidden|permission denied/.test(s))
    return { category: "infra/permission", severity: "critical", route: "IT" };
  if (/channel_not_found|not_in_channel|invalid_auth|invalid_charset/.test(s))
    return { category: "Slack/integration", severity: "critical", route: "IT" };
  if (/google sheets api has not been used|api has not been used|quota|rate limit|resource has been exhausted/.test(s))
    return { category: "Google API", severity: "critical", route: "IT" };
  // 2) lỗi dữ liệu do AI/người dùng → cần AP Clerk
  if (/missing required field|invalid (vendor|billto|invoicenumber|totalamount|currency|lineitems)|ai output is not/.test(s))
    return { category: "data/validation", severity: "warning", route: "AP Clerk" };
  // 3) tạm thời — đã hết retry (retryOnFail ×3) nên vẫn cần xử lý
  if (/429|503|502|timeout|etimedout|econnreset|fetch failed|experiencing high demand/.test(s))
    return { category: "transient (API)", severity: "warning", route: "AP Clerk" };
  // 4) không rõ → coi như nghiêm trọng
  return { category: "unknown", severity: "critical", route: "IT" };
}

const cls = classify();
const node = ex.lastNodeExecuted || "(unknown node)";
const exId = ex.id || "";
const ts = new Date().toISOString();
const excId = "EXC-" + ts.replace(/[-:T.Z]/g, "").slice(0, 14) + "-" + String(exId).slice(-4);

const execUrl = ex.url
  || ("http://127.0.0.1:5678/workflow/" + String(wf.id || "") + "/executions/" + String(exId));

const severityIcon = { critical: ":rotating_light:", warning: ":warning:", info: ":information_source:" };

return [{
  json: {
    exceptionId: excId,
    timestamp: ts,
    executionId: exId,
    failedNode: node,
    category: cls.category,
    severity: cls.severity,
    route: cls.route,
    errorMessage: msg,
    errorName: err.name || "",
    errorStack: stack.slice(0, 2000),
    executionUrl: execUrl,
    retryOf: ex.retryOf || "",
    mode: ex.mode || "",
    workflowName: wf.name || "",
    workflowId: wf.id || "",
    status: "Open",
    resolution: "",
    notes: "",
    slackText:
      severityIcon[cls.severity] + " *Workflow Error — " + cls.severity.toUpperCase() + "*\n"
      + "Exception: `" + excId + "` (route: " + cls.route + ")\n"
      + "Workflow: " + (wf.name || "?") + " (" + (wf.id || "?") + ")\n"
      + "Failed node: `" + node + "`\n"
      + "Category: " + cls.category + "\n"
      + "Error: " + msg.slice(0, 400) + "\n"
      + "Mode: " + (ex.mode || "?") + (ex.retryOf ? " (retry of " + ex.retryOf + ")" : "") + "\n"
      + "Execution: " + execUrl + "\n"
      + "_DLQ: hang da ghi vao tab Exceptions_",
  },
}];

